using System.ComponentModel;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Create the agent with tools
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research agent that searches the web for information and takes notes to summarize findings.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the take_note tool to record key findings as you discover them.
        3. After gathering enough information, provide a comprehensive summary of your findings.
        Be thorough but concise. Cite your sources when possible.
        """,
};

// Register tools
var tools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    Console.WriteLine($"\nResearching: {input}\n");

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
    };

    var invokeOptions = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = chatOptions,
    };

    await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");

    if (tools.Notes.Count > 0)
    {
        Console.WriteLine("--- Research Notes ---");
        foreach (var note in tools.Notes)
        {
            Console.WriteLine($"• {note}");
        }
        Console.WriteLine("----------------------\n");
    }

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a given query. Returns search result snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Use a simple web search approach via DuckDuckGo HTML
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            // Extract text snippets from result blocks
            var snippets = ExtractSnippets(html);
            if (snippets.Count == 0)
            {
                return $"No results found for: {query}";
            }

            return $"Search results for '{query}':\n" + string.Join("\n---\n", snippets.Take(5));
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The content of the note to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieve all notes taken so far during this research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return "Current notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public void ClearNotes() => _notes.Clear();

    private static List<string> ExtractSnippets(string html)
    {
        var snippets = new List<string>();
        const string marker = "result__snippet";

        var index = 0;
        while ((index = html.IndexOf(marker, index, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', index) + 1;
            if (start <= 0) break;

            var end = html.IndexOf('<', start);
            if (end <= start) { index = start; continue; }

            var text = System.Net.WebUtility.HtmlDecode(html[start..end]).Trim();
            if (!string.IsNullOrWhiteSpace(text))
            {
                snippets.Add(text);
            }

            index = end;
        }

        return snippets;
    }
}

