+/// <summary>
+/// Tools available to the research agent for web searching and note-taking.
+/// </summary>
+sealed class ResearchTools
+{
+    private readonly List<string> _notes = [];
+    private readonly HttpClient _httpClient = new();
+
+    public IReadOnlyList<string> Notes => _notes;
+
+    [Description("Search the web for information on a given query. Returns search result snippets.")]
+    public async Task<string> WebSearch(
+        [Description("The search query to look up")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        try
+        {
+            // Use a simple web search approach via DuckDuckGo HTML
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
+
+            using var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
+
+            var response = await _httpClient.SendAsync(request, cancellationToken);
+            var html = await response.Content.ReadAsStringAsync(cancellationToken);
+
+            // Extract text snippets from result blocks
+            var snippets = ExtractSnippets(html);
+            if (snippets.Count == 0)
+            {
+                return $"No results found for: {query}";
+            }
+
+            return $"Search results for '{query}':\n" + string.Join("\n---\n", snippets.Take(5));
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed for '{query}': {ex.Message}";
+        }
+    }
+
+    [Description("Take a note to record an important finding during research.")]
+    public string TakeNote(
+        [Description("The content of the note to save")] string note)
+    {
+        _notes.Add(note);
+        return $"Note saved ({_notes.Count} total notes).";
+    }
+
+    [Description("Retrieve all notes taken so far during this research session.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes taken yet.";
+        }
+
+        return "Current notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
+    }
+
+    public void ClearNotes() => _notes.Clear();
+
+    private static List<string> ExtractSnippets(string html)
+    {
+        var snippets = new List<string>();
+        const string marker = "result__snippet";
+
+        var index = 0;
+        while ((index = html.IndexOf(marker, index, StringComparison.Ordinal)) >= 0)
+        {
+            var start = html.IndexOf('>', index) + 1;
+            if (start <= 0) break;
+
+            var end = html.IndexOf('<', start);
+            if (end <= start) { index = start; continue; }
+
+            var text = System.Net.WebUtility.HtmlDecode(html[start..end]).Trim();
+            if (!string.IsNullOrWhiteSpace(text))
+            {
+                snippets.Add(text);
+            }
+
+            index = end;
+        }
+
+        return snippets;
+    }
+}

