using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Create the chat client directly
var openAIClient = new OpenAI.OpenAIClient(apiKey);
IChatClient chatClient = new OpenAIChatClient(openAIClient.GetChatClient(modelId));

// Define tools for the agent
var tools = new ResearchTools();
var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.TakeNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// Create the ChatClientAgent with tools and instructions
var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research agent that searches the web and takes notes to summarize findings.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the WebSearch tool to find relevant information (perform multiple searches with different queries).
        2. Use the TakeNote tool to record key findings as you discover them.
        3. After gathering enough information, provide a comprehensive summary of your findings.
        Be thorough but concise. Cite your sources when possible.
        """,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = aiTools,
    },
});

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    Console.WriteLine($"\nResearching: {input}\n");

    var response = await agent.RunAsync(
        $"Research the following topic and provide a summary: {input}");

    // Print the final assistant response
    foreach (var message in response.Messages)
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
        {
            Console.WriteLine(message.Text);
        }
    }

    Console.WriteLine();

    if (tools.Notes.Count > 0)
    {
        Console.WriteLine("--- Research Notes ---");
        foreach (var note in tools.Notes)
        {
            Console.WriteLine($"• {note}");
        }
        Console.WriteLine("----------------------\n");
    }

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

