using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define tools for the agent
var tools = new ResearchTools();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.TakeNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

const string instructions = """
    You are a research assistant. When given a topic:
    1. Use the WebSearch tool to find relevant information (perform multiple searches with different queries).
    2. Use the TakeNote tool to record key findings as you discover them.
    3. After gathering enough information, provide a comprehensive summary of your findings.
    Be thorough but concise. Cite your sources when possible.
    """;

// Create the ChatClientAgent which handles tool dispatch automatically
var innerAgent = new ChatClientAgent(chatClient, instructions, "ResearchAgent",
    "An AI research agent that searches the web and takes notes to summarize findings.", aiTools);

// Wrap with LoopAgent to allow multi-step tool calling iterations
var agent = new LoopAgent(innerAgent,
    new DelegateLoopEvaluator(context => context.LastResponse.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any())),
    new LoopAgentOptions { MaxIterations = 10 });

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    Console.WriteLine($"\nResearching: {input}\n");

    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    });

    var response = await agent.RunAsync(
        $"Research the following topic and provide a summary: {input}",
        session: null,
        runOptions);

    // Print the final assistant response
    foreach (var message in response.Messages)
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
        {
            Console.WriteLine(message.Text);
        }
    }

    Console.WriteLine();

    if (tools.Notes.Count > 0)
    {
        Console.WriteLine("--- Research Notes ---");
        foreach (var note in tools.Notes)
        {
            Console.WriteLine($"• {note}");
        }
        Console.WriteLine("----------------------\n");
    }

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

